WITH parsed AS (SELECT id, plan, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers) SELECT plan, CASE WHEN lowest_price >= 27 THEN 'LARGE' ELSE 'SMALL' END AS lowest_price_tier, COUNT(*) FILTER (WHERE plan = 'enterprise') AS enterprise_rows, PERCENTILE_APPROX(lowest_price, ARRAY(0.25, 0.5, 0.75)) AS lowest_price_quartiles, ROUND(AVG(lowest_price), 2) AS avg_lowest_price, COUNT(*) AS cnt, AVG(lowest_price) AS avg_lowest_price_2 FROM parsed GROUP BY 1, 2 ORDER BY avg_lowest_price
